<script setup lang="ts">import {ref,onMounted} from 'vue';import {datasets} from '../stores/datasets';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {units} from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import PairTable from '../components/PairTable.vue';const name=ref(''),text=ref(''),unit=ref('kPa'),description=ref(''),selected=ref('');const {error,busy,act}=useTask();onMounted(datasets.load);async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)text.value=await f.text()}function submit(){act(async()=>{await datasets.create({name:name.value,x_unit:unit.value,y_unit:unit.value,csv_text:text.value,description:description.value});name.value='';text.value=''})}</script><template><PageHeading index="01 / 配对观测" title="把两侧读数，按同一编号放在一起。" note="CSV列pair_id,range_label,x,y；量程low/middle/high。两侧必须同单位，最少4组才可计算，不自动换算。"/><div class="two-col"><section><Notice :message="datasets.error.value"/><article v-for="r in datasets.items.value" :key="r.id" class="dataset-row"><button class="record-open" @click="selected=selected===r.id?'':r.id"><h3>{{r.name}}</h3><p>{{r.pairs.length}}组 · X/Y={{r.x_unit}}/{{r.y_unit}} · {{r.description}}</p><span>预览成对读数 ↗</span></button><PairTable v-if="selected===r.id" :rows="r.pairs.slice(0,16)"/></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>导入配对批次</h2><label>批次名称<input v-model="name" required minlength="2"></label><label>共同单位<select v-model="unit"><option v-for="u in units" :key="u">{{u}}</option></select></label><label>CSV文件<input type="file" accept=".csv" @change="file"></label><label>配对CSV<textarea v-model="text" rows="8" required placeholder="pair_id,range_label,x,y"></textarea></label><label>采样说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并保存配对</button></form><aside v-else class="field-note">只读账号可核查原始读数。导入需要分析师权限。</aside></div></template>
